ey", "mode"], "properties": {"mode": {"enum": ["cohere"], "type": "string", "const": "cohere", "title": "Mode", "default": "cohere"}, "cohere_key": {"type": "string", "title": "Cohere API key", "airbyte_secret": true}}, "description": "Use the Cohere API to embed text."}, {"type": "object", "title": "Fake", "required": ["mode"], "properties": {"mode": {"enum": ["fake"], "type": "string", "const": "fake", "title": "Mode", "default": "fake"}}, "description": "Use a fake embedding made out of random vectors with 1536 embedding dimensions. This is useful for testing the data pipeline without incurring any costs."}, {"type": "object", "title": "Azure OpenAI", "required": ["openai_key", "api_base", "deployment", "mode"], "properties": {"mode": {"enum": ["azure_openai"], "type": "string", "const": "azure_openai", "title": "Mode", "default": "azure_openai"}, "api_base": {"type": "string", "title": "Resource base URL", "examples": ["https://your-resource-name.openai.azure.com"], "description": "The base URL for your Azure OpenAI resource.  You can find this in the Azure portal under your Azure OpenAI resource"}, "deployment": {"type": "string", "title": "Deployment", "examples": ["your-resource-name"], "description": "The deployment for your Azure OpenAI resource.  You can find this in the Azure portal under your Azure OpenAI resource"}, "openai_key": {"type": "string", "title": "Azure OpenAI API key", "description": "The API key for your Azure OpenAI resource.  You can find this in the Azure portal under your Azure OpenAI resource", "airbyte_secret": true}}, "description": "Use the Azure-hosted OpenAI API to embed text. This option is using the text-embedding-ada-002 model with 1536 embedding dimensions."}, {"type": "object", "title": "OpenAI-compatible", "required": ["base_url", "dimensions", "mode"], "properties": {"mode": {"enum": ["openai_compatible"], "type": "string", "const": "openai_compatible", "title": "Mode", "default": "openai_compatible"}, "api_key": {"type": "string", "title": "API key", "default": "", "airbyte_secret": true}, "base_url": {"type": "string", "title": "Base URL", "examples": ["https://your-service-name.com"], "description": "The base URL for your OpenAI-compatible service"}, "dimensions": {"type": "integer", "title": "Embedding dimensions", "examples": [1536, 384], "description": "The number of dimensions the embedding model is generating"}, "model_name": {"type": "string", "title": "Model name", "default": "text-embedding-ada-002", "examples": ["text-embedding-ada-002"], "description": "The name of the model to use for embedding"}}, "description": "Use a service that's compatible with the OpenAI API to embed text."}], "title": "Embedding", "description": "Embedding configuration"}, "processing": {"type": "object", "group": "processing", "title": "ProcessingConfigModel", "required": ["chunk_size"], "properties": {"chunk_size": {"type": "integer", "title": "Chunk size", "maximum": 8191, "minimum": 1, "description": "Size of chunks in tokens to store in vector store (make sure it is not too big for the context if your LLM)"}, "text_fields": {"type": "array", "items": {"type": "string"}, "title": "Text fields to embed", "default": [], "examples": ["text", "user.name", "users.*.name"], "always_show": true, "description": "List of fields in the record that should be used to calculate the embedding. The field list is applied to all streams in the same way and non-existing fields are ignored. If none are defined, all fields are considered text fields. When specifying text fields, you can access nested fields in the record by using dot notation, e.g. `user.name` will access the `name` field in the `user` object. It's also possible to use wildcards to access all fields in an object, e.g. `users.*.name` will access all `names` fields in all entries of the `users` array."}, "chunk_overlap": {"type": "integer", "title": "Chunk overlap", "default": 0, "description": "Size of overlap between chunks in tokens to store in